A terminal flag is not enough for this version because duplicate words matter. I store `ending` for complete copies and `passing` for copies that use each character node.

A small dry run: insert `car`, then `cart`. The `c`, `a`, and `r` nodes have `passing = 2`, while the `r` node has `ending = 1`. Therefore the prefix count for `car` is 2, and the exact count for `car` is 1.

```java
import java.util.HashMap;
import java.util.ArrayList;

class Trie {
    private static class Node {
        HashMap<Character, Node> children = new HashMap<>();
        int ending;
        int passing;
    }

    private final Node root;

    public Trie() {
        root = new Node();
    }

    public void insert(String word) {
        Node current = root;
        for (int i = 0; i < word.length(); i++) {
            char ch = word.charAt(i);
            Node next = current.children.get(ch);
            if (next == null) {
                next = new Node();
                current.children.put(ch, next);
            }
            current = next;
            current.passing++;
        }
        current.ending++;
    }

    public int countWordsEqualTo(String word) {
        Node node = find(word);
        return node == null ? 0 : node.ending;
    }

    public int countWordsStartingWith(String prefix) {
        if (prefix.length() == 0) {
            return 0;
        }
        Node node = find(prefix);
        return node == null ? 0 : node.passing;
    }

    public void erase(String word) {
        Node current = root;
        ArrayList<Node> path = new ArrayList<>();

        for (int i = 0; i < word.length(); i++) {
            Node next = current.children.get(word.charAt(i));
            if (next == null) {
                return;
            }
            current = next;
            path.add(current);
        }

        if (current.ending == 0) {
            return;
        }

        current.ending--;
        for (Node node : path) {
            node.passing--;
        }
    }

    private Node find(String text) {
        Node current = root;
        for (int i = 0; i < text.length(); i++) {
            current = current.children.get(text.charAt(i));
            if (current == null) {
                return null;
            }
        }
        return current;
    }
}
```

The traversal cost is `O(L)` on average for an input of length `L`. The stored nodes and their maps take `O(S)` space. Calling `erase` on a missing word does nothing, so counts cannot become negative.

I kept a count at every node. `wordCount` tells how many copies end there, while `prefixCount` tells how many inserted words pass through the node. That makes both counting methods direct, and erase only subtracts one copy.

The children use a fixed array because the input is made of lowercase English letters. For example, after inserting `apple` twice and `app` once, the node for `app` has `wordCount = 1` and `prefixCount = 3`.

```go
package main

type trieNode struct {
	children    [26]*trieNode
	wordCount   int
	prefixCount int
}

type Trie struct {
	root *trieNode
}

func Constructor() Trie {
	return Trie{root: &trieNode{}}
}

func (t *Trie) Insert(word string) {
	node := t.root
	for i := 0; i < len(word); i++ {
		index := int(word[i] - 'a')
		if node.children[index] == nil {
			node.children[index] = &trieNode{}
		}
		node = node.children[index]
		node.prefixCount++
	}
	node.wordCount++
}

func (t *Trie) CountWordsEqualTo(word string) int {
	node := t.find(word)
	if node == nil {
		return 0
	}
	return node.wordCount
}

func (t *Trie) CountWordsStartingWith(prefix string) int {
	node := t.find(prefix)
	if node == nil {
		return 0
	}
	return node.prefixCount
}

func (t *Trie) Erase(word string) {
	node := t.root
	path := make([]*trieNode, 0, len(word))

	for i := 0; i < len(word); i++ {
		index := int(word[i] - 'a')
		if node.children[index] == nil {
			return
		}
		node = node.children[index]
		path = append(path, node)
	}

	if node.wordCount == 0 {
		return
	}

	node.wordCount--
	for _, current := range path {
		current.prefixCount--
	}
}

func (t *Trie) find(text string) *trieNode {
	node := t.root
	for i := 0; i < len(text); i++ {
		index := int(text[i] - 'a')
		if node.children[index] == nil {
			return nil
		}
		node = node.children[index]
	}
	return node
}
```

Each operation takes `O(L)` time, where `L` is the word or prefix length. The trie uses `O(S)` space for `S` unique characters stored. Erase leaves unused nodes in place, which keeps the code simple.

The extra counts are more useful here than a simple end flag. Every node stores how many words go through it and how many complete words finish there. Inserting the same word twice increases both values along its path twice.

I used a sparse `unordered_map` for children. It saves the unused 26 pointers that a node would otherwise allocate, although hash lookups have more overhead than an array.

```cpp
#include <string>
#include <unordered_map>
#include <vector>
using namespace std;

class Trie {
    struct Node {
        unordered_map<char, Node*> children;
        int wordCount = 0;
        int prefixCount = 0;
    };

    Node* root;

    Node* walk(const string& text) const {
        Node* node = root;
        for (char ch : text) {
            auto it = node->children.find(ch);
            if (it == node->children.end()) {
                return nullptr;
            }
            node = it->second;
        }
        return node;
    }

public:
    Trie() {
        root = new Node();
    }

    void insert(string word) {
        Node* node = root;
        for (char ch : word) {
            if (!node->children.count(ch)) {
                node->children[ch] = new Node();
            }
            node = node->children[ch];
            node->prefixCount++;
        }
        node->wordCount++;
    }

    int countWordsEqualTo(string word) {
        Node* node = walk(word);
        return node == nullptr ? 0 : node->wordCount;
    }

    int countWordsStartingWith(string word) {
        Node* node = walk(word);
        return node == nullptr ? 0 : node->prefixCount;
    }

    void erase(string word) {
        Node* node = root;
        vector<Node*> path;

        for (char ch : word) {
            auto it = node->children.find(ch);
            if (it == node->children.end()) {
                return;
            }
            node = it->second;
            path.push_back(node);
        }

        if (node->wordCount == 0) {
            return;
        }

        node->wordCount--;
        for (Node* current : path) {
            current->prefixCount--;
        }
    }
};
```

For a word or prefix of length `L`, the time is `O(L)` on average. Space is `O(S)`, where `S` is the number of different character positions created. An empty prefix returns the root count, which is zero here because counts are stored on the word nodes, so this implementation assumes non-empty prefixes as normally used by the platform.

The structure below uses one node per prefix and keeps two integers in each node. `complete` handles exact duplicates, and `through` handles all words below that prefix. This also means `erase` can safely remove one copy without accidentally removing a prefix used by another word.

For example, after inserting `apple` twice, `countWordsEqualTo("apple")` is 2. After one erase it becomes 1, while every prefix count on the `apple` path also drops by one.

```csharp
using System.Collections.Generic;

public class Trie
{
    private class Node
    {
        public Dictionary<char, Node> Children = new Dictionary<char, Node>();
        public int Complete;
        public int Through;
    }

    private readonly Node root;

    public Trie()
    {
        root = new Node();
    }

    public void insert(string word)
    {
        Node current = root;
        foreach (char ch in word)
        {
            if (!current.Children.TryGetValue(ch, out Node next))
            {
                next = new Node();
                current.Children[ch] = next;
            }

            current = next;
            current.Through++;
        }

        current.Complete++;
    }

    public int countWordsEqualTo(string word)
    {
        Node node = Find(word);
        return node == null ? 0 : node.Complete;
    }

    public int countWordsStartingWith(string prefix)
    {
        Node node = Find(prefix);
        return node == null ? 0 : node.Through;
    }

    public void erase(string word)
    {
        Node current = root;
        List<Node> path = new List<Node>();

        foreach (char ch in word)
        {
            if (!current.Children.TryGetValue(ch, out Node next))
            {
                return;
            }

            current = next;
            path.Add(current);
        }

        if (current.Complete == 0)
        {
            return;
        }

        current.Complete--;
        foreach (Node node in path)
        {
            node.Through--;
        }
    }

    private Node Find(string text)
    {
        Node current = root;
        foreach (char ch in text)
        {
            if (!current.Children.TryGetValue(ch, out Node next))
            {
                return null;
            }
            current = next;
        }
        return current;
    }
}
```

The important edge case is erasing a word that was never inserted. The method returns before changing any counter. Empty strings also leave the root unchanged.

With `L` as the input length, insertion, lookup, and erase all take `O(L)` expected time. Space is `O(S)` for `S` trie nodes and their child dictionaries.

This version keeps the trie sparse with dictionaries and removes nodes after the last copy of a word disappears. The recursive helper walks to the end, decreases the counts on the way back, and reports whether a child can be deleted.

The cleanup is not required for correctness, but it prevents old branches from using space forever. The edge cases covered here are duplicate inserts, erasing a word that is not present, and erasing a shorter word that is a prefix of another word.

```python
class Trie:
    class Node:
        def __init__(self):
            self.children = {}
            self.words = 0
            self.prefixes = 0

    def __init__(self):
        self.root = self.Node()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = self.Node()
            node = node.children[char]
            node.prefixes += 1
        node.words += 1

    def countWordsEqualTo(self, word):
        node = self._find(word)
        return 0 if node is None else node.words

    def countWordsStartingWith(self, prefix):
        node = self._find(prefix)
        return 0 if node is None else node.prefixes

    def erase(self, word):
        self._erase(self.root, word, 0)

    def _erase(self, node, word, index):
        if index == len(word):
            if node.words == 0:
                return False
            node.words -= 1
            return len(node.children) == 0 and node.words == 0

        char = word[index]
        child = node.children.get(char)
        if child is None:
            return False

        remove_child = self._erase(child, word, index + 1)
        if child.prefixes > 0:
            child.prefixes -= 1

        if remove_child and child.prefixes == 0:
            del node.children[char]

        return len(node.children) == 0 and node.words == 0

    def _find(self, text):
        node = self.root
        for char in text:
            node = node.children.get(char)
            if node is None:
                return None
        return node
```

Dry run with `cat` and `cater`: removing `cat` reduces the count at `c`, `a`, and `t`, but the `t` node stays because it still leads to `cater`. The recursive cleanup only removes a branch when no word uses it.

Every operation visits at most `L` characters, so it takes `O(L)` time. The trie needs `O(S)` space for the characters that remain stored.

